(() => { const sh = document.querySelector('.sheet'), sr = sh.getBoundingClientRect(); const marks = [];
 document.querySelectorAll('.sheet mark.hl').forEach(m => { const cls = [...m.classList].find(c => /^hl-(blue|orange|yellow|green)$/.test(c)) || '';
   [...m.getClientRects()].forEach(r => marks.push({hl: m.dataset.hl, color: cls.slice(3), x: r.x - sr.x, y: r.y - sr.y, w: r.width, h: r.height})); });
 const cards = []; document.querySelectorAll('.margin-card, .margin-summary').forEach(c => { const r = c.getBoundingClientRect(); cards.push({cls: c.className, x: r.x, y: r.y, w: r.width, h: r.height, text: c.innerText.slice(0, 80)}); });
 let pre = document.getElementById('__dump'); if (!pre) { pre = document.createElement('pre'); pre.id = '__dump'; pre.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;overflow:hidden;opacity:0;white-space:pre;'; document.body.appendChild(pre); }
 pre.textContent = JSON.stringify({sheet: {x: sr.x, y: sr.y, w: sr.width, h: sr.height}, marks, cards}); })()
